// Check of the line length of the code in this repository, used locally and in CI.
//
// Usage (from any directory):
//   node .github/scripts/check-line-length.mjs
//
// CLAUDE.md and the .editorconfig allow at most 120 characters per line in all code: C#, TypeScript,
// Vue, JavaScript, CSS and shell scripts. The check reads the files that git tracks and reports every
// longer line. Prettier wraps the code of the web app at 100 characters and ESLint (@stylistic/max-len)
// reports long strings and comments there; this check covers all code, including the C# projects,
// the tests, the themes and the scripts.
// Not checked:
// - generated code: the EF Core migrations, the Kiota client of the web app and every file that marks
//   itself as generated (<auto-generated> or "Generated by Microsoft Kiota" near its start),
// - files of other kinds (Markdown, JSON, YAML, XML, SVG, Dockerfile), which are documents, data or
//   configuration rather than code,
// - a comment line that holds nothing but an address (https://...), which cannot be wrapped.
// Characters are counted as Unicode code points, a tab as one character (the .editorconfig asks for
// spaces). Exits with 0 if every line fits, otherwise with 1.

import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const scriptsDirectory = path.dirname(fileURLToPath(import.meta.url))
export const repositoryRoot = path.resolve(scriptsDirectory, '..', '..')

/** The longest line allowed (max_line_length of the .editorconfig). */
export const maxLineLength = 120

/** Extensions of the files that hold code. */
export const checkedExtensions = new Set([
    '.cs',
    '.ts',
    '.mts',
    '.cts',
    '.tsx',
    '.js',
    '.mjs',
    '.cjs',
    '.vue',
    '.css',
    '.sh',
])

/** Folders of generated code (paths relative to the repository root, with forward slashes). */
export const generatedFolders = ['source/WaveMP.Data/Migrations/', 'source/WaveMP.Web/src/api/generated/']

/** Markers of generated files, looked for in the first lines of a file. */
const generatedMarkers = ['<auto-generated', 'Generated by Microsoft Kiota']
const markerLines = 5

/** A comment line that holds only an address, such as `// https://...` or ` * <https://...>.` */
const addressOnlyComment = /^\s*(?:\/\/\/?|\*|\/\*|#)\s*<?https?:\/\/\S+$/

/** Whether the file at the path (relative, forward slashes) is code that the check reads. */
export function isCheckedPath(relativePath) {
    if (generatedFolders.some((folder) => relativePath.startsWith(folder))) {
        return false
    }
    if (relativePath.split('/').includes('node_modules')) {
        return false
    }
    return checkedExtensions.has(path.posix.extname(relativePath).toLowerCase())
}

/** Whether the text marks itself as generated code. */
export function isGenerated(text) {
    const head = text.split('\n', markerLines).join('\n')
    return generatedMarkers.some((marker) => head.includes(marker))
}

/** Number of characters of a line (Unicode code points, without a carriage return at its end). */
export function lineLength(line) {
    return [...line.replace(/\r$/, '')].length
}

/** The lines of the text that are longer than the limit: line number (from 1) and length. */
export function findLongLines(text, limit = maxLineLength) {
    const found = []
    text.split('\n').forEach((line, index) => {
        const length = lineLength(line)
        if (length > limit && !addressOnlyComment.test(line.replace(/\r$/, ''))) {
            found.push({ line: index + 1, length })
        }
    })
    return found
}

/** The files that git tracks below the root (paths relative to it, with forward slashes). */
export function listTrackedFiles(root) {
    const output = execFileSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'utf8', maxBuffer: 1 << 28 })
    return output.split('\0').filter((file) => file.length > 0)
}

/**
 * The problems of the files: one entry per line that is too long, with the path relative to the root.
 * readFile returns the text of a path relative to the root, or null for a file that is gone.
 */
export function findLineLengthProblems(files, readFile, limit = maxLineLength) {
    const problems = []
    for (const file of files) {
        if (!isCheckedPath(file)) {
            continue
        }
        const text = readFile(file)
        if (text === null || isGenerated(text)) {
            continue
        }
        for (const { line, length } of findLongLines(text, limit)) {
            problems.push({ file, line, length })
        }
    }
    return problems
}

/** The text of a problem: an annotation in GitHub Actions, otherwise path:line: message. */
export function formatProblem(problem, githubActions = false, limit = maxLineLength) {
    const message = `Line has ${problem.length} characters, at most ${limit} are allowed.`
    return githubActions
        ? `::error file=${problem.file},line=${problem.line}::${message}`
        : `${problem.file}:${problem.line}: ${message}`
}

function readTextFile(root, file) {
    try {
        return readFileSync(path.join(root, file), 'utf8')
    } catch (error) {
        if (error.code === 'ENOENT') {
            return null
        }
        throw error
    }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    const files = listTrackedFiles(repositoryRoot)
    const problems = findLineLengthProblems(files, (file) => readTextFile(repositoryRoot, file))
    if (problems.length > 0) {
        const githubActions = process.env.GITHUB_ACTIONS === 'true'
        for (const problem of problems) {
            console.error(formatProblem(problem, githubActions))
        }
        console.error(`${problems.length} line(s) longer than ${maxLineLength} characters; wrap them.`)
        process.exit(1)
    }
    console.log(`Every line of code has at most ${maxLineLength} characters.`)
}
